import { Flex } from '@chakra-ui/react';
import Icon from './Icon';

export default function CheckBox(props: { checked: boolean; width?: string; height?: string; borderRadius?: string; onClick: () => void }) {
  const { checked, width, height, borderRadius, onClick } = props
  return (
    <Flex
      align="center"
      justifyContent="center"
      background="checked_bg"
      border="1px solid"
      borderColor="border"
      cursor="pointer"
      width={width || '20px'}
      height={height || '20px'}
      borderRadius={borderRadius || '4px'}
      onClick={onClick}
      sx={{
        svg: {
          fill: 'primary !important'
        }
      }}
    >
      {checked ? <Icon xlinkHref="#icon-icon_check" /> : null}
    </Flex>
  )
}
